window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"Lp5-354A0Zk","speaker":"Khalifa bin Shaheen Al Marar","role":"Minister of State","country":"United Arab Emirates","region":"Middle East","url":"https://www.youtube.com/watch?v=Lp5-354A0Zk","date":"20260928","title":"🇦🇪 United Arab Emirates - Minister of State Addresses United Nations General Debate, 81st Session","seconds":720,"words":1533,"counts":{"claims":17,"promises":3,"attacks":1},"topics":[{"topic":"Gaza","share":0.1871,"seconds":135},{"topic":"UAE environment","share":0.1085,"seconds":78},{"topic":"Iran","share":0.0947,"seconds":68},{"topic":"UAE governance","share":0.0914,"seconds":66},{"topic":"UAE economy","share":0.0906,"seconds":65},{"topic":"UAE strategy","share":0.089,"seconds":64},{"topic":"UN reform","share":0.0877,"seconds":63},{"topic":"UAE diplomacy","share":0.0875,"seconds":63},{"topic":"global trade","share":0.0838,"seconds":60},{"topic":"UAE culture","share":0.0797,"seconds":57}],"timeline":[[1,65,"UAE strategy"],[68,136,"Iran"],[137,197,"global trade"],[199,262,"UAE diplomacy"],[263,325,"Gaza"],[328,400,"Gaza"],[402,465,"UN reform"],[466,532,"UAE governance"],[534,599,"UAE economy"],[602,680,"UAE environment"],[682,740,"UAE culture"]],"stances":{"UAE strategy":"Khalifa bin Shaheen Al Marar states that the United Arab Emirates stands tall and is guided by a clear vision to transform challenges into achievements.","Iran":"The speaker asserts that the UAE maintains a principled approach of de-escalation and diplomacy while calling for a peaceful settlement to Iran's occupation of three Emirati islands.","global trade":"The speaker emphasizes securing supply chains under international law and lists various regions where the UAE has supported peace efforts, including specific positions on Yemen, Libya, the Sahel, DRC, Myanmar, Haiti, the Moroccan Sahara, and Ukraine.","UAE diplomacy":"The UAE asserts it has successfully mediated 26 exchanges involving nearly 8,000 prisoners between Ukraine and Russia and calls for a ceasefire and independent government in Sudan.","Gaza":"The UAE supports the international framework to end the war in Gaza and calls for full implementation of President Trump's plan, including Israeli withdrawal, Hamas disarmament, and a two-state solution.","UN reform":"Khalifa bin Shaheen Al Marar emphasizes the need to strengthen multilateral institutions like the UN and calls for proactive crisis prevention under new leadership.","UAE governance":"Khalifa bin Shaheen Al Marar states that the UAE model has demonstrated resilience and capacity to deliver tangible results through strategic independence, industrial capabilities, and economic partnerships.","UAE economy":"The speaker states that the UAE is committed to expanding its role as a global hub and increasing investments in artificial intelligence, emerging technologies, health care, and the energy sector.","UAE environment":"The UAE is co-hosting a UN conference on water with Senegal and views the initiative as a commitment to turning water scarcity into an opportunity for innovation.","UAE culture":"The speaker states that the UAE is investing in tolerance and inclusion, building a society with full female participation and youth partnership, and remains committed to moderation and rejecting violence."},"claims":[{"t":102,"quote":"As Iran continues its occupation of the three Emirati islands, Greater Tunb, Lesser Tunb, and Abu Musa","topic":"Iran","kind":"fact"},{"t":157,"quote":"We have continued to support every sincere effort to achieve peace, particularly in Yemen, Libya, the Sahel, the Democratic Republic of the Congo, Myanmar, Haiti, and elsewhere.","topic":"global trade","kind":"fact"},{"t":169,"quote":"We have also supported efforts to reach a sustainable political solution to the question of the Moroccan Sahara based on the Moroccan autonomy initiative while affirming the sovereignty of the Kingdom of Morocco over the Sahara.","topic":"global trade","kind":"fact"},{"t":184,"quote":"Furthermore, we have advocated for a comprehensive, just, and lasting peace in Ukraine in accordance with international law and the principles of the UN Charter, including respect for sovereignty, independence, and territorial integrity.","topic":"global trade","kind":"fact"},{"t":203,"quote":"successfully conducting 26 mediations that facilitated the exchange of nearly 8,000 prisoners between Ukraine and the Russian Federation","topic":"UAE diplomacy","kind":"number"},{"t":282,"quote":"the UAE was among the first to support the framework established by the international community to end the horrific war.","topic":"Gaza","kind":"fact"},{"t":291,"quote":"We have stressed the need to fully implement the comprehensive plan of President Trump to end the conflict in Gaza and the associated roadmap, including the withdrawal of Israel from the Gaza Strip, the disarmament of Hamas, and the advancement of a serious political horizon leading to a just and lasting settlement of the Palestinian question based on the two-state","topic":"Gaza","kind":"fact"},{"t":374,"quote":"Today, that commitment continues through our role as the largest provider of humanitarian aid to Gaza","topic":"Gaza","kind":"fact"},{"t":404,"quote":"the importance of developing and reforming regional and international multilateral institutions remains paramount to strengthen their capacity to fulfill their responsibilities, foremost among them the UN, including the Security Council.","topic":"UN reform","kind":"fact"},{"t":451,"quote":"my country has refused to let the crisis surrounding us undermine the world-leading achievements we have built over decades.","topic":"UN reform","kind":"self_credit"},{"t":485,"quote":"The UAE model has demonstrated its resilience and its capacity to deliver tangible results by investing in key pillars of national strength","topic":"UAE governance","kind":"fact"},{"t":534,"quote":"We will continue to strengthen the UAE's role as a global hub connecting markets and capital, opening ever broader horizons for growth.","topic":"UAE economy","kind":"fact"},{"t":572,"quote":"The UAE continues to expand its investments in artificial intelligence, emerging technologies, health care, and","topic":"UAE economy","kind":"fact"},{"t":602,"quote":"This year, the UAE is preparing to co-host with Senegal the UN Water Recognizing the importance of concerted coordinate coordinated international action in confronting the challenges of water, climate, and food security.","topic":"UAE environment","kind":"fact"},{"t":662,"quote":"Two days ago, Abu Dhabi also hosted the opening of the 15th UN Congress on Crime Prevention and Criminal Justice, which highlights the need to keep pace with rapid technological advancement and to protect societies from the impacts of crime, violence, and exploitation.","topic":"UAE environment","kind":"fact"},{"t":683,"quote":"we are investing in the values of tolerance, peaceful coexistence, and inclusion through partnerships that bring together diverse nationalities and religions.","topic":"UAE culture","kind":"fact"},{"t":693,"quote":"We are building a society in which women participate fully, equally, and And in which young people are genuine partners in shaping their future.","topic":"UAE culture","kind":"fact"}],"promises":[{"t":534,"quote":"We will continue to strengthen the UAE's role as a global hub connecting markets and capital, opening ever broader horizons for growth.","topic":"UAE economy","kind":"promise"},{"t":545,"quote":"This is the promise that the UAE makes to its people and to all who call it home.","topic":"UAE economy","kind":"promise"},{"t":705,"quote":"my country will remain committed to the path of moderation, the rejection of violence and extremism, and the investment in people and in the vast potential with which our region is so richly endowed.","topic":"UAE culture","kind":"promise"}],"attacks":[{"t":343,"quote":"We further underscore the urgent need to halt Israel's dangerous escalation in the West Bank in the West Bank and its settlement activities accompanied by the rise of settler violence, terrorism, and the siege of Palestinian village, as well as the ongoing violations in East Jerusalem and at the holy sites, and the attempts to impose a new historical and legal status quo on the ground. My country strongly condemns all these actions.","topic":"Gaza","target":"Israel"}],"greece":[],"said":[],"pickup":[],"transcript":[{"t":1,"topic":"UAE strategy","text":"I now give the floor to his Excellency Khalifa bin Shaheen Al Marar, Minister of State at the Ministry of Foreign Affairs of the United Arab Emirates. &gt;&gt; Bismillah al-Rahman al-Rahim. &gt;&gt; In the name of God, the merciful, the compassionate. Mr. President, our region and the world are undergoing a period of rapid transformation marked by intensifying challenges and divisions. Against this backdrop, the United Arab Emirates stands tall, guided by a clear vision and unwavering to transform challenges into to turn ambitions into achievements, and to open new horizons for peace, development, and prosperity for our people, the peoples of the region, and the world."},{"t":68,"topic":"Iran","text":"This stems from our principled approach rooted in de-escalation, the promotion of diplomacy and dialogue, the peaceful settlement of disputes, and the rejection of the unlawful use or threat of use of force, as well as This approach is grounded in full respect for the sovereignty of states, good neighborly relations, international law, and the UN Charter. These values have long underpinned our domestic and foreign policies. As Iran continues its occupation of the three Emirati islands, Greater Tunb, Lesser Tunb, and Abu Musa, which we the United Arab Emirates has consistently called for a peaceful settlement of this conflict, whether through direct negotiations or by recourse to the International Court of Justice. Amid growing threats to navigation in our region and beyond my country has continued to emphasize the principles of freedom of navigation and the right of transit passage."},{"t":137,"topic":"global trade","text":"We stress the need to secure and protect the safe flow of supply chains, trade, and energy in accordance with international law, including the law of the sea and the principle of state sovereignty recognizing these as pillars of food security, development, and prosperity of We have continued to support every sincere effort to achieve peace, particularly in Yemen, Libya, the Sahel, the Democratic Republic of the Congo, Myanmar, Haiti, and elsewhere. We have also supported efforts to reach a sustainable political solution to the question of the Moroccan Sahara based on the Moroccan autonomy initiative while affirming the sovereignty of the Kingdom of Morocco over the Sahara. Furthermore, we have advocated for a comprehensive, just, and lasting peace in Ukraine in accordance with international law and the principles of the UN Charter, including respect for sovereignty, independence, and territorial integrity."},{"t":199,"topic":"UAE diplomacy","text":"We have remained steadfast in our role as a trusted international mediator, successfully conducting 26 mediations that facilitated the exchange of nearly 8,000 prisoners between Ukraine and the Russian Federation, ensuring their return to their homelands and families. The UAE has also stood ready to support nations undergoing positive transformations such as Syria and as they move towards a secure and stable Regarding Sudan my country has underscored the need to end the humanitarian catastrophe, securing a permanent and unconditional ceasefire that would bring an end to the civil war. This includes launching a comprehensive and credible political process led by which would culminate in the formation of a civil government independent of both parties to the conflict and from extremist groups. It is crucial to ensure that neither side of the conflict has a role in the new civilian government."},{"t":263,"topic":"Gaza","text":"The future of Sudan must be decided solely by the Sudanese people, and the international community must press the leaders of Port Sudan authorities and those of the Rapid Support Forces as parties to the conflict to engage seriously with international initiatives. As for Gaza, the UAE was among the first to support the framework established by the international community to end the horrific war. We have stressed the need to fully implement the comprehensive plan of President Trump to end the conflict in Gaza and the associated roadmap, including the withdrawal of Israel from the Gaza Strip, the disarmament of Hamas, and the advancement of a serious political horizon leading to a just and lasting settlement of the Palestinian question based on the two-state This entails the establishment of an independent sovereign Palestinian state living side by side with Israel in peace and security."},{"t":328,"topic":"Gaza","text":"We also underscore the importance of ensuring the unification of Gaza and the West Bank under a Palestinian authority that, once reformed, will be capable to fulfill its responsibilities and ensure that arms remain solely under its control. We further underscore the urgent need to halt Israel's dangerous escalation in the West Bank in the West Bank and its settlement activities accompanied by the rise of settler violence, terrorism, and the siege of Palestinian village, as well as the ongoing violations in East Jerusalem and at the holy sites, and the attempts to impose a new historical and legal status quo on the ground. My country strongly condemns all these actions. For decades, the UAE's commitment to the Palestinian people has remained unwavering. Today, that commitment continues through our role as the largest provider of humanitarian aid to Gaza, along with our humanitarian and development projects in the West Bank. This role reflects the core values of our foreign policy, which is driven by the spirit of giving through effective international partnerships, while reconfirming the principles of international humanitarian law and protection of civilians."},{"t":402,"topic":"UN reform","text":"Across all these dossiers, the importance of developing and reforming regional and international multilateral institutions remains paramount to strengthen their capacity to fulfill their responsibilities, foremost among them the UN, including the Security Council. The United Nations, as the United Nations prepares to transition to a new leadership, we look forward to the next Secretary General using his or her good offices to activate preventive and mediation mechanisms before the first signs of crisis emerge, rather than merely reacting once they have erupted. Crisis should be addressed at their roots, not simply managed. Mr. President, my country has refused to let the crisis surrounding us undermine the world-leading achievements we have built over decades. We have pressed ahead with progress across every sector."},{"t":466,"topic":"UAE governance","text":"For this nation was forged not in the absence of challenges, but in defiance of them. The peoples of the region aspire to stability and prosperity in an environment defined by cooperation, moderation, and tolerance, not by violence, hatred, extremism, or The UAE model has demonstrated its resilience and its capacity to deliver tangible results by investing in key pillars of national strength, foremost among them strategic independence, industrial capabilities, advanced defense systems, and world-class infrastructure and This is complemented by the empowerment of human capital, building a knowledge and innovation-based economy, and the harnessing of the opportunities offered by the comprehensive economic economic partnership agreements concluded between the UAE and 38 nations, and other frameworks to diversify markets and supply chains, and to broaden horizons for trade and investment."},{"t":534,"topic":"UAE economy","text":"We will continue to strengthen the UAE's role as a global hub connecting markets and capital, opening ever broader horizons for growth. This is the promise that the UAE makes to its people and to all who call it home. And it is also the bedrock of our international partnerships, particularly with the nations of the global south and the African continent, which have matured into an enduring strategic cooperation rooted in mutual respect and shared interests. The UAE continues to expand its investments in artificial intelligence, emerging technologies, health care, and We are also strengthening our position as a trusted and responsible leader in the energy sector, balancing the needs of today with bold investment and solutions of tomorrow. And driving the historic commitments of the UAE consensus toward long-term collective action."},{"t":602,"topic":"UAE environment","text":"This year, the UAE is preparing to co-host with Senegal the UN Water Recognizing the importance of concerted coordinate coordinated international action in confronting the challenges of water, climate, and food security. We are confident that the conference will mark a vital milestone in advancing real practical solutions for water security. We invite you to participate in the conference and look forward to welcoming you in Abu Dhabi. This effort embody our firm commitment to turning the challenge of water scarcity into an opportunity for innovation and joint international action, including through the Mohammed bin Zayed Water Initiative, which harnesses innovation, partnership, and investment to deliver lasting sustainable solutions for present and future generations. Two days ago, Abu Dhabi also hosted the opening of the 15th UN Congress on Crime Prevention and Criminal Justice, which highlights the need to keep pace with rapid technological advancement and to protect societies from the impacts of crime, violence, and exploitation."},{"t":682,"topic":"UAE culture","text":"At the same time, we are investing in the values of tolerance, peaceful coexistence, and inclusion through partnerships that bring together diverse nationalities and religions. We are building a society in which women participate fully, equally, and And in which young people are genuine partners in shaping their future. In conclusion, Mr. President, my country will remain committed to the path of moderation, the rejection of violence and extremism, and the investment in people and in the vast potential with which our region is so richly endowed. We extend our hands to our partners in the region and the world to build rather than destroy, and to unite rather than divide. Thank you, President. &gt;&gt; I thank I thank the Minister of State at the Ministry of Foreign Affairs of the United Arab Emirates."}],"compare":[{"topic":"Israel–Palestine","share":0.1871,"mean":0.0517,"rank":12,"others":76},{"topic":"Iran","share":0.0947,"mean":0.0133,"rank":10,"others":25},{"topic":"UN & its reform","share":0.0877,"mean":0.2054,"rank":149,"others":170},{"topic":"United Arab Emirates","share":0.0875,"mean":0.0,"rank":1,"others":0},{"topic":"Global Trade","share":0.0838,"mean":0.0043,"rank":5,"others":7}]};
